  Lemma c1eA_inner : forall f s B0 U0 j c R dtj dtS m1 mC (x10 x12 x18 x19 x28 x29 x30 : word),
    Z.of_nat f = n - j -> 0 <= j < n -> b <= s < e -> 4 * U0 = 4 * start + B0 -> 0 <= B0 -> U0 + L <= Z.of_nat ncells ->
    0 <= R < 2^64 ->
